<?php
namespace App\Services\Cobros;
use App\Models\{AccountReceivable,CobrosCredit,CobrosCreditInstallment,CobrosCreditInstallmentComponent,CobrosCreditRequest,CobrosCreditRenewalRequest,Company};
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
class RenewedCreditBuilder {
 public function __construct(private InstallmentScheduleService $schedule){}
 public function build(Company $company,CobrosCreditRenewalRequest $renewal,array $quote,CobrosCredit $previous): CobrosCredit {
  return DB::transaction(function()use($company,$renewal,$quote,$previous){
   if((int)$previous->company_id!==(int)$company->id)throw ValidationException::withMessages(['renewal'=>'Crédito fuera de la empresa.']);
   $existing=CobrosCredit::where('company_id',$company->id)->whereJsonContains('terms_snapshot->renewal_request_id',$renewal->id)->first();if($existing)return $existing;
   $customer=$previous->customer;$branch=$company->branches()->where('is_active',true)->orderBy('id')->firstOrFail();
   $request=CobrosCreditRequest::create(['company_id'=>$company->id,'cobros_route_id'=>$previous->cobros_route_id,'collector_user_id'=>$renewal->collector_user_id,'customer_id'=>$customer->id,'status'=>CobrosCreditRequest::STATUS_APPROVED,'identification_type'=>'cedula','identification'=>(string)$customer->identification,'name'=>(string)$customer->name,'phone'=>(string)($customer->phone??''),'address'=>(string)($customer->address??''),'amount_requested'=>$quote['consolidated_total'],'notes'=>'Renovación interna #'.$renewal->id,'submitted_at'=>now()]);
   $account=AccountReceivable::create(['company_id'=>$company->id,'branch_id'=>$branch->id,'cobros_route_id'=>$previous->cobros_route_id,'customer_id'=>$customer->id,'issued_at'=>today(),'due_date'=>$quote['schedule']['rows'][0]['due_date'],'original_amount'=>$quote['consolidated_total'],'balance_due'=>$quote['consolidated_total'],'status'=>AccountReceivable::STATUS_PENDING,'currency_code'=>$company->currency]);
   $credit=CobrosCredit::create(['company_id'=>$company->id,'credit_request_id'=>$request->id,'customer_id'=>$customer->id,'collector_user_id'=>$renewal->collector_user_id,'cobros_route_id'=>$previous->cobros_route_id,'account_receivable_id'=>$account->id,'principal'=>bcadd((string)$quote['previous_pending_principal'],(string)$quote['new_money']['principal'],4),'interest_type'=>CobrosCredit::INTEREST_NONE,'interest_value'=>'0','total_due'=>$quote['consolidated_total'],'installment_count'=>$quote['schedule']['installment_count'],'frequency'=>$quote['schedule']['frequency'],'first_due_date'=>$quote['schedule']['first_due_date'],'late_fee_type'=>$previous->late_fee_type,'late_fee_value'=>$previous->late_fee_value,'late_fee_grace_days'=>$previous->late_fee_grace_days,'status'=>CobrosCredit::STATUS_APPROVED,'terms_snapshot'=>['source'=>'renewal_builder','renewal_request_id'=>$renewal->id,'previous_credit_id'=>$previous->id,'late_fee_type'=>$previous->late_fee_type,'late_fee_value'=>$previous->late_fee_value,'late_fee_grace_days'=>$previous->late_fee_grace_days,'late_fee_cap_policy'=>$previous->terms_snapshot['late_fee_cap_policy']??null,'components'=>$renewal->contract_components]]);
   $kinds=['principal_refinanced'=>'previous_pending_principal','principal_new'=>'new_capital','interest_refinanced'=>'previous_pending_interest','interest_current'=>'new_interest'];$rows=$quote['schedule']['rows'];
   foreach($rows as $row){$i=CobrosCreditInstallment::create(['credit_id'=>$credit->id,'number'=>$row['number'],'due_date'=>$row['due_date'],'contractual_amount'=>$row['contractual_amount'],'applied_amount'=>'0','status'=>CobrosCreditInstallment::STATUS_PENDING]);foreach($kinds as $kind=>$key){$total=(string)match($key){'new_capital'=>$quote['new_money']['principal'],'new_interest'=>$quote['new_money']['interest'],'previous_pending_principal'=>$quote['previous']['principal'],default=>$quote['previous']['interest']};$amount=$this->schedule->round4(bcdiv($total,(string)count($rows),10));if((int)$row['number']===count($rows))$amount=bcsub($total,(string)CobrosCreditInstallmentComponent::where('credit_id',$credit->id)->where('kind',$kind)->sum('original_amount'),4);if(bccomp($amount,'0',4)>0)CobrosCreditInstallmentComponent::create(['credit_id'=>$credit->id,'installment_id'=>$i->id,'kind'=>$kind,'original_amount'=>$amount,'applied_amount'=>'0','source_credit_id'=>in_array($kind,['principal_refinanced','interest_refinanced'],true)?$previous->id:null,'source_renewal_id'=>$renewal->id]);}}
   return $credit->fresh();
  });
 }
}
